package eu.kanade.tachiyomi.data.recovery

import eu.kanade.tachiyomi.data.backup.models.Backup
import eu.kanade.tachiyomi.data.backup.models.BackupCategory
import eu.kanade.tachiyomi.data.backup.models.IntPreferenceValue
import eu.kanade.tachiyomi.data.backup.models.StringSetPreferenceValue
import tachiyomi.domain.download.service.DownloadPreferences
import tachiyomi.domain.library.service.LibraryPreferences

/** Compare portable meaning, not database IDs regenerated by a fresh installation. */
internal object RecoveryBackupIntegrity {
    fun verify(before: Backup, after: Backup) {
        val expected = snapshot(before)
        val actual = snapshot(after)
        check(expected.all { (key, value) -> actual[key] == value }) { "Portable data verification failed" }
    }
    private fun snapshot(backup: Backup): Map<List<String>, Any?> = buildMap {
        fun categories(ids: List<Long>, available: List<BackupCategory>) = ids.map { id ->
            available.firstOrNull { it.id == id }?.name ?: "default"
        }.toSet()
        backup.backupAnime.forEach { entry ->
            val key = listOf("anime", entry.source.toString(), entry.url)
            put(
                key,
                listOf(
                    entry.favorite,
                    entry.title,
                    entry.episodeFlags,
                    entry.viewer_flags,
                    categories(entry.categories, backup.backupAnimeCategories),
                ),
            )
            entry.episodes.forEach { item ->
                put(
                    key + listOf("episode", item.url),
                    listOf(item.seen, item.lastSecondSeen, item.bookmark, item.fillermark),
                )
            }
            entry.history.forEach { item -> put(key + listOf("history", item.url), item.lastRead) }
            entry.tracking.forEach { item ->
                put(
                    key + listOf("track", item.syncId.toString()),
                    listOf(item.mediaId, item.libraryId, item.lastEpisodeSeen, item.status, item.score),
                )
            }
        }
        backup.backupManga.forEach { entry ->
            val key = listOf("manga", entry.source.toString(), entry.url)
            put(
                key,
                listOf(
                    entry.favorite,
                    entry.title,
                    entry.chapterFlags,
                    entry.viewer_flags ?: entry.viewer,
                    categories(entry.categories, backup.backupCategories),
                ),
            )
            entry.chapters.forEach { item ->
                put(key + listOf("chapter", item.url), listOf(item.read, item.lastPageRead, item.bookmark))
            }
            entry.history.forEach { item -> put(key + listOf("history", item.url), item.lastRead) }
            entry.tracking.forEach { item ->
                put(
                    key + listOf("track", item.syncId.toString()),
                    listOf(item.mediaId, item.libraryId, item.lastChapterRead, item.status, item.score),
                )
            }
        }
        backup.backupAnimeCategories.forEach { put(listOf("anime_category", it.name), it.flags) }
        backup.backupCategories.forEach { put(listOf("manga_category", it.name), it.flags) }
        val animeKeys = LibraryPreferences.animeCategoryPreferenceKeys + DownloadPreferences.animeCategoryPreferenceKeys
        val mangaKeys = LibraryPreferences.mangaCategoryPreferenceKeys + DownloadPreferences.mangaCategoryPreferenceKeys
        backup.backupPreferences.forEach { item ->
            val known = when {
                item.key in animeKeys || item.key == LibraryPreferences.DEFAULT_ANIME_CATEGORY_PREF_KEY -> {
                    backup.backupAnimeCategories
                }
                item.key in mangaKeys || item.key == LibraryPreferences.DEFAULT_MANGA_CATEGORY_PREF_KEY -> {
                    backup.backupCategories
                }
                else -> null
            }
            val value: Any = when {
                known != null && item.value is IntPreferenceValue -> {
                    known.firstOrNull { it.id == item.value.value.toLong() }?.name ?: item.value
                }
                known != null && item.value is StringSetPreferenceValue -> item.value.value.map { id ->
                    known.firstOrNull { it.id.toString() == id }?.name ?: id
                }.toSet()
                else -> item.value
            }
            put(listOf("preference", item.key), value)
        }
        backup.backupSourcePreferences.forEach { source ->
            source.prefs.forEach {
                put(listOf("source_preference", source.sourceKey, it.key), it.value)
            }
        }
        backup.backupMangaExtensionRepo.forEach { put(listOf("manga_store", it.baseUrl), it.signingKeyFingerprint) }
        backup.backupAnimeExtensionStores.forEach { put(listOf("anime_store", it.indexUrl), it.signingKey) }
        backup.backupExtensions.forEach {
            // Backup bytes must survive; imported execution consent is deliberately not portable.
            put(listOf("extension", it.pkgName), if (it.format == "rin") it.copy(rinEnabled = false) else it)
        }
        backup.releaseSubscriptions.forEach {
            put(listOf("release_subscription", it.medium, it.source.toString(), it.url), it)
        }
        backup.backupCustomButton.forEach {
            put(
                listOf("button", it.name),
                listOf(it.content, it.longPressContent, it.onStartup, it.isFavorite, it.sortIndex),
            )
        }
        backup.backupHiddenResume?.let { put(listOf("hidden_resume"), it) }
    }
}
